import {baseUri} from '@jetbrains/teamcity-ui'
import React from 'react'

import BuildNumberContainer from '../../../../../components/common/BuildNumber/BuildNumber.container'
import {RouterButton} from '../../../../../components/common/RouterLink/RouterLink'
import EntityPath from '../../../../../containers/EntityPath'
import type {BuildId, BuildTypeId} from '../../../../../types'
import type {PercentageData} from '../../types'
import Percentage from '../Percentage/Percentage'

import styles from './BuildCoverage.module.css'

type Props = {
  buildId?: BuildId
  buildTypeId?: BuildTypeId
  statistics: PercentageData[]
  numCols?: number
  reportTabId?: string
}

const Filler: React.FC<{count: number}> = React.memo(function Filler({count}) {
  const arrayOfNulls = Array(count).fill(null)
  return (
    <>
      {arrayOfNulls.map((_, index) => (
        // eslint-disable-next-line react/no-array-index-key
        <div key={index} />
      ))}
    </>
  )
})

function BuildCoverage({buildId, buildTypeId, statistics, numCols, reportTabId}: Props) {
  let emptyCols = 0
  if (numCols != null) {
    emptyCols = numCols - statistics.length
    if (reportTabId != null) {
      emptyCols -= 1
    }
  }
  const partOfComposite = buildId != null && buildTypeId != null
  const root = baseUri.replace(location.origin, '')
  const buildUrl = partOfComposite ? `${root}/buildConfiguration/${buildTypeId}/${buildId}` : ''
  return (
    <div className={styles.row}>
      {partOfComposite && (
        <div className={styles.path}>
          <EntityPath
            buildId={buildId}
            buildTypeId={buildTypeId}
            linkClassName={styles.link}
            withLeafIcon
            withLeafStatusIcon={false}
            withCollapsing
          />
          <span>{'\u00a0/\u00a0' /* slash */}</span>
          <BuildNumberContainer className={styles.number} buildId={buildId} hideStar />
        </div>
      )}
      <div className={styles.data}>
        {statistics.map(percentageData => (
          <Percentage {...percentageData} key={percentageData.type} />
        ))}
        <Filler count={emptyCols} />
        {reportTabId != null && (
          <div className={styles.reportButtonCell}>
            <RouterButton
              to={`${buildUrl}?buildTab=${reportTabId}`}
              className={styles.reportButton}
            >
              {'Show report'}
            </RouterButton>
          </div>
        )}
      </div>
    </div>
  )
}

export default React.memo(BuildCoverage)
