import classNames from 'classnames'

import type {PercentageData} from '../../types'

import styles from './Percentage.module.css'

const GOOD = 50
const OK = 30
const TEN = 10
const TOTAL_PERCENTS = 100

function getColor(pct: number) {
  if (pct > GOOD) {
    return styles.green
  }
  if (pct > OK) {
    return styles.yellow
  }
  return styles.red
}

function round(x: number, fractionDigits = 1) {
  const powerOfTen = TEN ** fractionDigits
  return Math.floor(x * powerOfTen) / powerOfTen
}

function stringifyDiff(diff: number) {
  return `${diff > 0 ? '+' : ''}${round(diff, 2)}%`
}

type Props = PercentageData

function Percentage({type, total, covered, diff}: Props) {
  const pct = TOTAL_PERCENTS * (covered / total)
  const fraction = `${covered}/${total}`
  return (
    <div className={styles.wrapper}>
      <div className={styles.label}>
        <span className={styles.type}>{type}</span>
        <span title={fraction}>{`\u00a0${round(pct)}%`}</span>
        {diff != null && (
          <span className={styles.diff}>
            {'Diff:&#32;'}
            <span className={classNames(diff > 0 && styles.positive, diff < 0 && styles.negative)}>
              {stringifyDiff(diff)}
            </span>
          </span>
        )}
      </div>
      <div className={styles.progressWrapper} title={fraction}>
        <div className={styles.progress}>
          <div className={classNames(styles.bar, getColor(pct))} style={{width: `${pct}%`}} />
        </div>
      </div>
    </div>
  )
}

export default Percentage
