import type {BuildCoverageData, ReportData} from '../../types'
import BuildCoverage from '../BuildCoverage/BuildCoverage'

import styles from './Report.module.css'

function isSingle(report: ReportData): report is BuildCoverageData {
  return (report as unknown[]).map === undefined
}

type CompositeBuildCoverageProps = {
  report: BuildCoverageData[]
}

function CompositeBuildCoverage({report}: CompositeBuildCoverageProps) {
  const numCols = Math.max(
    ...report.map(data => data.statistics.length + (data.reportTabId != null ? 1 : 0)),
  )
  return (
    <>
      {report.map(buildCoverageData => (
        <BuildCoverage
          {...buildCoverageData}
          key={buildCoverageData.buildTypeId}
          numCols={numCols}
        />
      ))}
    </>
  )
}

type Props = {
  report: ReportData
}

function ReportComponent({report}: Props) {
  return (
    <div className={styles.wrapper}>
      {isSingle(report) ? (
        <BuildCoverage statistics={report.statistics} reportTabId={report.reportTabId} />
      ) : (
        <CompositeBuildCoverage report={report} />
      )}
    </div>
  )
}

export default ReportComponent
