import Link from '@jetbrains/ring-ui-built/components/link/link'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {utils} from '@jetbrains/teamcity-ui'
import type {PluginContext} from '@jetbrains/teamcity-ui'
import TCComponents from '@jetbrains/teamcity-ui/dist/components'
import {HTTPCodesEnum} from '@jetbrains/teamcity-ui/dist/services'
import React from 'react'

import type {ReportData} from '../../types'
import ReportComponent from '../Report/Report'

import styles from './App.module.css'

function App(context: PluginContext) {
  const buildId = context.location.buildId
  const [summary, setSummary] = React.useState<ReportData | null>(null)
  const [error, setError] = React.useState(false)
  const [loading, setLoading] = React.useState(true)
  const fetchReport = React.useCallback(() => {
    setLoading(true)
    utils
      .requestJSON<ReportData>(`app/coverage/buildData?buildId=${buildId}`)
      .then(report => {
        setSummary(report)
        setError(false)
        setLoading(false)
      })
      .catch(e => {
        if (e.statusCode !== HTTPCodesEnum.NOT_FOUND) {
          setError(true)
        }
        setLoading(false)
      })
  }, [buildId])
  React.useEffect(fetchReport, [buildId, fetchReport])

  return error ? (
    <div className={styles.placeholder}>
      {loading ? (
        <LoaderInline>{'Loading...'}</LoaderInline>
      ) : (
        <>
          <span className={styles.error}>{'Could not load code coverage summary.'}</span>{' '}
          <Link
            href="#"
            onClick={e => {
              e.preventDefault()
              fetchReport()
            }}
          >
            {'Try again'}
          </Link>
        </>
      )}
    </div>
  ) : (
    summary && (
      <TCComponents.ContentPanel
        heading="Code coverage"
        panelType="pluginCoverage"
        content={<ReportComponent report={summary} />}
      />
    )
  )
}

export default App
